/**
 * The `@polyjose/wasm` backend: the wasm-bindgen glue (`polyjose_wasm.js`, generated by
 * `wasm-pack build --target web`) adapted to the shared facade's `Backend` contract
 * (`bindings/js/BACKEND.md`, ADR 0031 §1, §3).
 *
 * - Every operation is the glue's export of the same camelCase name (ADR 0030 §2). The glue
 *   types record results as `object`; the Rust adapter builds them with exactly the
 *   `Backend*` shapes (`bindings/wasm/src/write.rs`), so they are asserted here, and the facade
 *   still checks every result field before returning it (ADR 0031 §1).
 * - `ready()` instantiates the module lazily, on the first call of any operation, so no entry
 *   uses top-level await (ADR 0031 §3). How the bytes or the `WebAssembly.Module` are found
 *   differs per runtime, so each entry (`node.mts`, `browser.mts`, `workerd.mts`) registers
 *   its loader with {@link setLoader} before anything can call the API.
 * - Errors are the glue's own: a core failure is a JS `Error` named `PolyjoseError` with a
 *   stable `code` (ADR 0030 §5, ADR 0031 §3), which the facade re-wraps.
 */
import type {
  Backend,
  BackendJweDecrypted,
  BackendJwsVerified,
  BackendJwtNestedVerified,
  BackendJwtVerified,
} from "./facade/backend.js";
import * as glue from "./polyjose_wasm.js";

/** Instantiates the wasm module; the glue makes a repeated call a no-op. */
export type Loader = () => void | Promise<void>;

let loader: Loader | undefined;

/**
 * Registers how this runtime instantiates the module. Called once by the package entry that
 * the `exports` conditions selected (ADR 0031 §3), when that entry is evaluated.
 */
export function setLoader(load: Loader): void {
  loader = load;
}

/** The glue as the facade's backend (BACKEND.md). */
export const backend: Backend = {
  /**
   * Awaited once by the facade before the first call; if it rejects, the call rejects with this
   * error and the next call tries again (BACKEND.md).
   */
  async ready(): Promise<void> {
    const load = loader;
    if (load === undefined) {
      throw new Error("polyjose: no WebAssembly loader registered (import @polyjose/wasm, not its internal files)");
    }
    await load();
  },
  version: () => glue.version(),
  errorCodes: () => glue.errorCodes(),

  base64urlEncode: (bytes) => glue.base64urlEncode(bytes),
  base64urlDecode: (text) => glue.base64urlDecode(text),

  jwkParse: (jwk) => glue.jwkParse(jwk),
  jwkToPublic: (jwk) => glue.jwkToPublic(jwk),
  jwkThumbprint: (jwk, hash) => glue.jwkThumbprint(jwk, hash),
  jwkThumbprintUri: (jwk, hash) => glue.jwkThumbprintUri(jwk, hash),
  jwksSelect: (jwks, selector) => glue.jwksSelect(jwks, selector),
  jwkGenerateOct: (lenBytes) => glue.jwkGenerateOct(lenBytes),
  jwkGenerateEc: (crv) => glue.jwkGenerateEc(crv),
  jwkGenerateOkp: (crv) => glue.jwkGenerateOkp(crv),
  jwkGenerateForAlg: (alg) => glue.jwkGenerateForAlg(alg),
  jwkFromPem: (pem) => glue.jwkFromPem(pem),
  jwkFromDer: (der, format) => glue.jwkFromDer(der, format),
  jwkToPem: (jwk, format) => glue.jwkToPem(jwk, format),
  jwkToDer: (jwk, format) => glue.jwkToDer(jwk, format),

  jwsSignCompact: (payload, key, options) => glue.jwsSignCompact(payload, key, options),
  jwsSignFlattened: (payload, signer, detached) => glue.jwsSignFlattened(payload, signer, detached),
  jwsSignGeneral: (payload, signers, detached) => glue.jwsSignGeneral(payload, signers, detached),
  jwsVerifyCompact: (token, key, options) => glue.jwsVerifyCompact(token, key, options) as BackendJwsVerified,
  jwsVerifyJson: (jws, key, options) => glue.jwsVerifyJson(jws, key, options) as BackendJwsVerified,

  jweEncryptCompact: (plaintext, options) => glue.jweEncryptCompact(plaintext, options),
  jweEncryptJson: (plaintext, options, form) => glue.jweEncryptJson(plaintext, options, form),
  jweDecryptCompact: (token, key, options) => glue.jweDecryptCompact(token, key, options) as BackendJweDecrypted,
  jweDecryptJson: (jwe, key, options) => glue.jweDecryptJson(jwe, key, options) as BackendJweDecrypted,

  jwtSign: (claims, key, options) => glue.jwtSign(claims, key, options),
  jwtVerify: (token, key, options) => glue.jwtVerify(token, key, options) as BackendJwtVerified,
  jwtVerifyWithJwks: (token, jwks, options) => glue.jwtVerifyWithJwks(token, jwks, options) as BackendJwtVerified,
  jwtEncryptNested: (signedJwt, options) => glue.jwtEncryptNested(signedJwt, options),
  jwtDecryptNested: (token, decryptKey, decryptOptions, key, verifyOptions) =>
    glue.jwtDecryptNested(token, decryptKey, decryptOptions, key, verifyOptions) as BackendJwtNestedVerified,
  jwtDecryptNestedWithJwks: (token, decryptKey, decryptOptions, jwks, verifyOptions) =>
    glue.jwtDecryptNestedWithJwks(token, decryptKey, decryptOptions, jwks, verifyOptions) as BackendJwtNestedVerified,
};
